INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('7af771db-0a58-4627-b7a6-99f6e4f23400', NULL, 'system', 'notifications.insert', 'notifications', '8a0f1b76-d482-40c5-98d5-2f60d0a32083', NULL, '{"id":"8a0f1b76-d482-40c5-98d5-2f60d0a32083","name":"Courier could not reach","event":"DELIVERY_FAILED","channel":"EMAIL","subject":"We could not deliver order {{ order.name }}","wa_body":null,"wa_name":null,"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>The courier could not reach you</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">{% if order.name %}Order {{ order.name }}{% endif %}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">The courier could not reach you</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, the courier tried to deliver your order {{ order.name }} but could not reach you.</p>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">To get it delivered, {% if shop.phone %}call us at {{ shop.phone }} or {% endif %}reply to this email.</p>\n</td></tr>\n{% if shipment.tracking_url or order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ shipment.tracking_url | default: order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Track your parcel</a>\n</td></tr>{% endif %}\n\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>","wa_params":null,"wa_reason":null,"wa_status":null,"conditions":[],"created_at":"2026-10-29T09:29:22.067235+00:00","is_enabled":false,"updated_at":"2026-10-29T09:29:22.067235+00:00","wa_buttons":false,"wa_version":0,"merchant_id":"00000000-0000-4000-8000-000000000001","wa_language":null,"reply_buttons":false,"wa_checked_at":null,"wa_template_id":null}', '{}', '2026-10-29T09:29:22.067Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('fc87bbea-ecf3-4f20-bade-4cfdf90c67c3', NULL, 'system', 'notifications.insert', 'notifications', '28a264ba-d939-4496-ad6d-9ce90b36ce4a', NULL, '{"id":"28a264ba-d939-4496-ad6d-9ce90b36ce4a","name":"Abandoned cart reminder","event":"CART_REMINDER","channel":"SMS","subject":null,"wa_body":null,"wa_name":null,"template":"You left items in your cart ({{cart_total}}). Finish your order: {{cart_url}} - {{store_name}}","wa_params":null,"wa_reason":null,"wa_status":null,"conditions":[],"created_at":"2026-10-29T09:29:22.067235+00:00","is_enabled":false,"updated_at":"2026-10-29T09:29:22.067235+00:00","wa_buttons":false,"wa_version":0,"merchant_id":"00000000-0000-4000-8000-000000000001","wa_language":null,"reply_buttons":false,"wa_checked_at":null,"wa_template_id":null}', '{}', '2026-10-29T09:29:22.067Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('ca39b4e7-10b0-4638-970b-cec0018fb533', NULL, 'system', 'notifications.insert', 'notifications', '1c196923-0495-4943-bbb6-82653b9be70a', NULL, '{"id":"1c196923-0495-4943-bbb6-82653b9be70a","name":"Abandoned cart reminder","event":"CART_REMINDER","channel":"WHATSAPP","subject":null,"wa_body":null,"wa_name":null,"template":"Hi {{customer_first_name}}, you left items worth {{cart_total}} in your cart. Finish your order here: {{cart_url}} and pay on delivery.\n\nThe {{store_name}} team","wa_params":null,"wa_reason":null,"wa_status":null,"conditions":[],"created_at":"2026-10-29T09:29:22.067235+00:00","is_enabled":false,"updated_at":"2026-10-29T09:29:22.067235+00:00","wa_buttons":false,"wa_version":0,"merchant_id":"00000000-0000-4000-8000-000000000001","wa_language":null,"reply_buttons":false,"wa_checked_at":null,"wa_template_id":null}', '{}', '2026-10-29T09:29:22.067Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('614e27fb-3d7a-41d9-9987-26cfd225d769', NULL, 'system', 'notifications.insert', 'notifications', '8ebdf369-1441-4030-b2bc-96d95ffaa26d', NULL, '{"id":"8ebdf369-1441-4030-b2bc-96d95ffaa26d","name":"Abandoned cart reminder","event":"CART_REMINDER","channel":"EMAIL","subject":"You left something in your cart","wa_body":null,"wa_name":null,"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your cart is waiting</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">{% if order.name %}Order {{ order.name }}{% endif %}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your cart is waiting</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, you left these items in your cart at {{ shop.name }}. Finish your order in a minute and pay on delivery.</p>\n</td></tr>\n{% if cart.url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ cart.url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Finish your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in cart.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;\">{{ cart.total | money }}</td></tr>\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>","wa_params":null,"wa_reason":null,"wa_status":null,"conditions":[],"created_at":"2026-10-29T09:29:22.067235+00:00","is_enabled":false,"updated_at":"2026-10-29T09:29:22.067235+00:00","wa_buttons":false,"wa_version":0,"merchant_id":"00000000-0000-4000-8000-000000000001","wa_language":null,"reply_buttons":false,"wa_checked_at":null,"wa_template_id":null}', '{}', '2026-10-29T09:29:22.067Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('bcbd6039-74f4-4b9c-a512-813263b04c25', NULL, 'system', 'notifications.insert', 'notifications', '999402bd-3fc3-46b9-b533-f3d6c6572c20', NULL, '{"id":"999402bd-3fc3-46b9-b533-f3d6c6572c20","name":"Review request","event":"REVIEW_REQUEST","channel":"SMS","subject":null,"wa_body":null,"wa_name":null,"template":"How was your order {{order_number}}? Please leave a quick review: {{review_url}} - {{store_name}}","wa_params":null,"wa_reason":null,"wa_status":null,"conditions":[],"created_at":"2026-10-29T09:29:22.067235+00:00","is_enabled":false,"updated_at":"2026-10-29T09:29:22.067235+00:00","wa_buttons":false,"wa_version":0,"merchant_id":"00000000-0000-4000-8000-000000000001","wa_language":null,"reply_buttons":false,"wa_checked_at":null,"wa_template_id":null}', '{}', '2026-10-29T09:29:22.067Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('2f8e7f3f-36a5-4753-be2c-4a571ff5dc6c', NULL, 'system', 'notifications.insert', 'notifications', 'accf96d2-444f-445c-bde6-90f5b7669f12', NULL, '{"id":"accf96d2-444f-445c-bde6-90f5b7669f12","name":"Review request","event":"REVIEW_REQUEST","channel":"WHATSAPP","subject":null,"wa_body":null,"wa_name":null,"template":"Hi {{customer_first_name}}, how do you like your order {{order_number}}? A quick review would help us a lot: {{review_url}} Thank you!\n\nThe {{store_name}} team","wa_params":null,"wa_reason":null,"wa_status":null,"conditions":[],"created_at":"2026-10-29T09:29:22.067235+00:00","is_enabled":false,"updated_at":"2026-10-29T09:29:22.067235+00:00","wa_buttons":false,"wa_version":0,"merchant_id":"00000000-0000-4000-8000-000000000001","wa_language":null,"reply_buttons":false,"wa_checked_at":null,"wa_template_id":null}', '{}', '2026-10-29T09:29:22.067Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('6cb6d0cf-71ce-4938-b0f3-67865996495f', NULL, 'system', 'notifications.insert', 'notifications', '835ac6cc-9ab6-4603-9181-844b4449f4cf', NULL, '{"id":"835ac6cc-9ab6-4603-9181-844b4449f4cf","name":"Review request","event":"REVIEW_REQUEST","channel":"EMAIL","subject":"How was your order {{ order.name }}?","wa_body":null,"wa_name":null,"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>How did we do?</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">{% if order.name %}Order {{ order.name }}{% endif %}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">How did we do?</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, we hope you love your order {{ order.name }}. A one-minute review helps other shoppers, and it helps us a lot.</p>\n</td></tr>\n{% if shop.review_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ shop.review_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Write a review</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>","wa_params":null,"wa_reason":null,"wa_status":null,"conditions":[],"created_at":"2026-10-29T09:29:22.067235+00:00","is_enabled":false,"updated_at":"2026-10-29T09:29:22.067235+00:00","wa_buttons":false,"wa_version":0,"merchant_id":"00000000-0000-4000-8000-000000000001","wa_language":null,"reply_buttons":false,"wa_checked_at":null,"wa_template_id":null}', '{}', '2026-10-29T09:29:22.067Z', '00000000-0000-4000-8000-000000000001');
