600;padding:12px 22px;border-radius:8px;">অর্ডার দেখুন</a>⏎</td></tr>{% endif %}⏎<tr><td style="padding:8px 32px 0;">⏎<p style="margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;">অর্ডারের বিবরণ</p>⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎{% for item in order.line_items %}<tr>⏎<td width="56" style="padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;">{% if item.image_url %}<img src="{{ item.image_url }}" alt="" width="48" height="48" style="display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;">{% endif %}</td>⏎<td style="padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;">{{ item.title }}{% if item.variant_title %}<br><span style="color:#6b7280;font-size:13px;">{{ item.variant_title }}</span>{% endif %}<br><span style="color:#6b7280;font-size:13px;">পরিমাণ {{ item.quantity }}</span></td>⏎<td align="right" style="padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;">{{ item.line_price | money }}</td>⏎</tr>{% endfor %}⏎</table>⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:8px;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">সাবটোটাল</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.subtotal_price | money }}</td></tr>⏎{% if order.discount_price > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">ছাড়</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">-{{ order.discount_price | money }}</td></tr>{% endif %}⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">ডেলিভারি চার্জ</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.delivery_price | money }}</td></tr>⏎<tr><td style="padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;">মোট</td><td align="right" style="padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;">{{ order.total_price | money }}</td></tr>⏎{% if order.paid_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">পরিশোধিত</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.paid_amount | money }}</td></tr>{% endif %}⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;"><strong>ডেলিভারিতে পরিশোধ</strong></td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}⏎</table>⏎</td></tr>⏎{% if order.shipping_address.address %}<tr><td style="padding:20px 32px 0;">⏎<p style="margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;">ডেলিভারি ঠিকানা</p>⏎<p style="margin:0;font-size:14px;line-height:1.6;color:#374151;">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>⏎</td></tr>{% endif %}⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), 'bn');
